import{_ as t,o as s,c as e,ag as r}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-10-25（材料 / 柔性钙钛矿组件 / 界面解耦）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/materials/science-daily-2026-10-25-materials.md","filePath":"topics/materials/science-daily-2026-10-25-materials.md"}'),n={name:"topics/materials/science-daily-2026-10-25-materials.md"};function i(a,o,c,l,d,g){return s(),e("div",null,[...o[0]||(o[0]=[r('<h1 id="科学日报-·-2026-10-25-材料-柔性钙钛矿组件-界面解耦" tabindex="-1">科学日报 · 2026-10-25（材料 / 柔性钙钛矿组件 / 界面解耦） <a class="header-anchor" href="#科学日报-·-2026-10-25-材料-柔性钙钛矿组件-界面解耦" aria-label="Permalink to &quot;科学日报 · 2026-10-25（材料 / 柔性钙钛矿组件 / 界面解耦）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-25.md</code> — 第44期 ｜ 科学板块（1 篇） 落盘说明：文件名带 <code>-materials</code> 后缀以<strong>避免与其它主题同日同名文件互引产生伪边</strong>（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-10-25-柔性钙钛矿组件破-20-——把「锚定」与「结晶」两个步骤拆开" tabindex="-1">科学日报 2026-10-25：柔性钙钛矿组件破 20%——把「锚定」与「结晶」两个步骤拆开 <a class="header-anchor" href="#科学日报-2026-10-25-柔性钙钛矿组件破-20-——把「锚定」与「结晶」两个步骤拆开" aria-label="Permalink to &quot;科学日报 2026-10-25：柔性钙钛矿组件破 20%——把「锚定」与「结晶」两个步骤拆开&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-25.md</code> ｜ DOI: 10.1126/science.aef9745</p></blockquote><ul><li>问题定位（很具体）：<strong>柔性钙钛矿太阳能组件（PSM）的效率与稳定性长期低于刚性器件</strong>，根因之一是<strong>柔性基底表面羟基容易脱附</strong> → 破坏<strong>自组装单分子层（SAM）的锚定</strong> → 进一步<strong>扰乱钙钛矿结晶</strong>。也就是说：<strong>底界面的锚定</strong>与<strong>体相结晶</strong>这两个本该分开的步骤，在工艺上被<strong>耦合</strong>在一起，互相拖累。</li><li>解法：<strong>解耦的 SAM–钙钛矿共沉积（decoupled SAM-perovskite codeposition）</strong>——<strong>降低 SAM 与钙钛矿之间的相互作用</strong>，从而<strong>加速 SAM 锚定</strong>、并<strong>改善钙钛矿结晶</strong>。</li><li>关键数据： <ul><li>钝化分子 <strong>碘化苯乙铵（PEAI）</strong>：<strong>750 cm²</strong> 面积组件，<strong>认证效率 20.2%</strong>；</li><li>钝化剂 <strong>1,3-丙二胺二氢碘盐（DAPDI）</strong>：<strong>14.55 cm²</strong> 器件 <strong>22.0%</strong>，在 <strong>85°C、65% RH</strong> 下<strong>最大功率点跟踪 1044 小时仅衰减 8%</strong>；</li><li><strong>通过柔性便携 PSM 国际商业化评估标准的所有序列测试</strong>（这条是「工程可交付」信号，不只是实验室效率）。</li></ul></li><li>洞察（对本库 <code>materials</code> × <code>physics</code>）：本条的通用范式是「<strong>解耦</strong>」。同一个界面上有两个竞争过程（SAM 锚定要快、钙钛矿结晶要慢且有序），它们<strong>共享同一组相互作用</strong>因而互相干扰；作者的做法不是「同时优化两者」，而是<strong>先把二者的耦合项压下去</strong>（降低 SAM–钙钛矿相互作用），让两个过程各自跑到自己的最优，再靠<strong>钝化分子选择</strong>决定最终表面质量。 <ul><li>对照本库同族主线：10-09「挥发性共晶调控钙钛矿结晶」（用<strong>相变温度/时序</strong>当指令）、10-24「交替+脉冲热输入打印米级单晶」（用<strong>热历史</strong>当指令）——<strong>三条都在说同一件事：晶体/薄膜的质量由「工艺时序的先后与耦合方式」决定，而不是由原料配方单点决定</strong>。可迁移判据：<strong>当两个必要的物理过程互相打架时，先问它们是否共享同一个耦合通道；能拆开耦合，比分别调参更根本。</strong></li><li>迁移到外脑工作流：<strong>「采集」与「沉淀」若共用同一步骤就会互相拖累</strong>（采集要快、沉淀要慢且结构化）——正是本库 <code>memory/</code>（raw、快、不过滤）与 <code>topics/</code>（沉淀、慢、结构化）两层设计的物理依据。</li></ul></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/materials/index.md</code> ｜ 第44期 科学板块</p></blockquote><p>关键词：柔性钙钛矿太阳能组件、PSM、自组装单分子层、SAM 锚定、柔性基底表面羟基脱附、SAM–钙钛矿共沉积、解耦、碘化苯乙铵 PEAI、1,3-丙二胺二氢碘盐 DAPDI、750 cm² 认证 20.2%、14.55 cm² 22.0%、85°C 65%RH 1044 h 衰减 8%、国际商业化评估标准、耦合通道、解耦优于联合优化、采集与沉淀分层</p><p>关联：<code>topics/materials/science-daily-2026-10-09.md</code>（钙钛矿共晶调控）、<code>topics/materials/science-daily-2026-10-24-materials.md</code>（时序即指令）、<code>topics/materials/index.md</code>、<code>topics/physics/index.md</code></p>',10)])])}const u=t(n,[["render",i]]);export{p as __pageData,u as default};
